"""Files a project needs once to run UAC tests with evidence. Never overwrites existing files."""

from __future__ import annotations

from pathlib import Path

from . import store

PLAYWRIGHT_CONFIG = """\
// Generated by qa-review for acceptance-criteria (UAC) tests. Safe to edit.
import {{ defineConfig }} from '@playwright/test';

export default defineConfig({{
  testDir: './{tests_dir}',
  outputDir: process.env.QA_REVIEW_UAC_ARTIFACTS || './.qa-review/uac/artifacts',
  fullyParallel: true,
  retries: 0,
  reporter: [
    ['json', {{ outputFile: process.env.QA_REVIEW_UAC_JSON || './.qa-review/uac/results.json' }}],
    ['line'],
  ],
  use: {{
    baseURL: process.env.BASE_URL,                       // the host given to `uac_run` / --host
    channel: process.env.QA_REVIEW_BROWSER_CHANNEL || undefined,   // e.g. 'chrome' to use installed Chrome
    screenshot: 'on',                                    // final screenshot of every UI test = evidence
    trace: 'retain-on-failure',
    video: (process.env.QA_REVIEW_VIDEO as 'on' | 'off' | 'retain-on-failure') || 'retain-on-failure',  // needs ffmpeg
    extraHTTPHeaders: process.env.QA_REVIEW_API_TOKEN
      ? {{ Authorization: `Bearer ${{process.env.QA_REVIEW_API_TOKEN}}` }} : undefined,
  }},
}});
"""

EVIDENCE = """\
// Evidence helpers for UAC tests (generated by qa-review). Everything attached here shows up,
// per UAC, in the qa-review report.
import { test, type Page, type APIRequestContext, type APIResponse } from '@playwright/test';

const SECRET = /authorization|cookie|token|secret|password|api[-_]?key/i;
const hide = (h: Record<string, string> = {}) =>
  Object.fromEntries(Object.entries(h).map(([k, v]) => [k, SECRET.test(k) ? '[hidden]' : v]));

/** Screenshot of the page right now, labelled (use it after each visible Then). */
export async function shot(page: Page, label: string): Promise<void> {
  await test.info().attach(`shot: ${label}`, { body: await page.screenshot({ fullPage: true }), contentType: 'image/png' });
}

/** Free-text evidence: ids created, values read, anything a reviewer should see. */
export async function note(text: string): Promise<void> {
  await test.info().attach('note', { body: text, contentType: 'text/plain' });
}

type Method = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

/** An HTTP call that records request and response (secrets hidden) as evidence. */
export async function apiCall(request: APIRequestContext, method: Method, url: string, data?: unknown,
                              options: { headers?: Record<string, string> } = {}): Promise<APIResponse> {
  const res = await request.fetch(url, { method, data, headers: options.headers });
  const text = await res.text();
  let body: unknown = text;
  try { body = JSON.parse(text); } catch { /* not JSON: keep the text */ }
  await test.info().attach(`api: ${method} ${url}`, {
    contentType: 'application/json',
    body: JSON.stringify({
      request: { method, url: res.url(), headers: hide(options.headers), data: data ?? null },
      response: { status: res.status(), headers: hide(res.headers()), body },
    }, null, 2),
  });
  return res;
}
"""


def ensure(root: Path) -> list[str]:
    """Create the Playwright config and the evidence helpers if missing. Returns the files created."""
    st = store.settings(root)
    created = []
    targets = {
        Path(root) / st.playwright_config: PLAYWRIGHT_CONFIG.format(tests_dir=st.tests_dir.strip("/")),
        Path(root) / st.tests_dir / "evidence.ts": EVIDENCE,
    }
    for p, text in targets.items():
        if not p.exists():
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(text, encoding="utf-8")
            created.append(str(p.relative_to(root)))
    return created
